$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';$root='C:\JudasValidation';$base='http://192.168.122.1:8872';$out="$root\M78ColdRepairFinalResults";$name='m78-final-repair-editor';$scratch="$root\M78FinalRepairEditor"
function Upload($p,$n){Invoke-WebRequest -UseBasicParsing "$base/$n" -Method Post -InFile $p|Out-Null}
try{
 if(Test-Path $scratch){throw 'Preserve previous editor scratch'};if((Get-PSDrive C).Free -lt 42MB){throw 'Insufficient editor headroom'};New-Item -ItemType Directory $scratch|Out-Null
 $m=(Invoke-WebRequest -UseBasicParsing "$base/m78-final-repair-editor.json").Content|ConvertFrom-Json;$library=[IO.File]::ReadAllText("$out\m78-final-repair-library.json")|ConvertFrom-Json;if((Get-FileHash $library.archive).Hash.ToLower() -ne $library.archiveSHA256){throw 'New final archive changed'};$objects=@();$rows=@()
 foreach($u in $m.objects){$source=Join-Path "$root\Source" $u.source;if((Get-FileHash $source).Hash.ToLower() -ne $u.sourceSHA256){throw 'Unchanged editor source mismatch'};$obj="$scratch\$($u.objectName)";Invoke-WebRequest -UseBasicParsing $u.url -OutFile $obj;if((Get-Item $obj).Length -ne $u.bytes -or (Get-FileHash $obj).Hash.ToLower() -ne $u.objectSHA256){throw 'Preserved editor object mismatch'};$objects+=$obj;$rows+=$u}
 Import-Module "$root\VS2022\Common7\Tools\Microsoft.VisualStudio.DevShell.dll";Enter-VsDevShell -VsInstallPath "$root\VS2022" -SkipAutomaticLocation -DevCmdArguments '-arch=x64 -host_arch=x64';Set-Location "$root\Build";$exe="$root\Build\Release\$name.exe";if(Test-Path $exe){throw 'Preserve previous editor executable'};$link=[string]$m.linkFlags;$link=[regex]::Replace($link,'/OUT:"[^"]*"',('/OUT:"'+$exe+'"'),'IgnoreCase');$link=[regex]::Replace($link,'RELEASE\\JUDAS_ENGINE\.LIB',('"'+$library.archive+'"'),'IgnoreCase');$link=[regex]::Replace($link,'/PDB:"[^"]*"',('/PDB:"'+$scratch+'\link.pdb"'),'IgnoreCase');$link=[regex]::Replace($link,'/IMPLIB:"[^"]*"',('/IMPLIB:"'+$scratch+'\editor.lib"'),'IgnoreCase');$link=[regex]::Replace($link,'\s+JUDAS_EDITOR\.DIR\\RELEASE\\[^\s]+\.OBJ',' ','IgnoreCase');foreach($obj in $objects){$link+=' "'+$obj+'"'};$rsp="$scratch\link.rsp";[IO.File]::WriteAllText($rsp,$link,[Text.UTF8Encoding]::new($false));$log="$out\$name-link.log";[IO.File]::WriteAllText($log,'');$ErrorActionPreference='Continue';& link.exe "@$rsp" 2>&1|Tee-Object -FilePath $log;$code=$LASTEXITCODE;Upload $log ([IO.Path]::GetFileName($log));if($code -ne 0){throw 'Final editor relink failed'}
 $rp="$out\$name-build.json";@{scope=$m.scope;objects=$rows;librarySHA256=$library.archiveSHA256;executable=$exe;executableSHA256=(Get-FileHash $exe).Hash.ToLower();executableBytes=(Get-Item $exe).Length;linkerResponse=$link}|ConvertTo-Json -Depth 6|Set-Content $rp -Encoding UTF8;Upload $rp ([IO.Path]::GetFileName($rp))
 $owned="$out\editor-project";if(Test-Path $owned){throw 'Preserve original editor project copy'};Copy-Item "$root\Source\projects\balance_lab" $owned -Recurse;$scene="$owned\Scenes\standing.judas";$before=(Get-FileHash $scene).Hash.ToLower();$env:GALLIUM_DRIVER='llvmpipe';$env:JUDAS_ENGINE_ROOT="$root\Source";$env:JUDAS_EDITOR_AUTOTEST="$out\editor-autotest";foreach($n in @('JUDAS_TEST_SCRIPT','M78_DIAGNOSTIC_PERSIST_DRIVE_IMPULSES','JUDAS_BOUNDARY_REPLAY_CAPTURED_NATIVE','JUDAS_BOUNDARY_REPLAY_MODE')){[Environment]::SetEnvironmentVariable($n,$null,'Process')}
 $watch=[Diagnostics.Stopwatch]::StartNew();$p=Start-Process -FilePath $exe -WorkingDirectory "$root\Source" -ArgumentList @("$owned\balance_lab.judasproj") -PassThru -RedirectStandardOutput "$out\$name.stdout.log" -RedirectStandardError "$out\$name.stderr.log";[void]$p.Handle;if(!$p.WaitForExit(600000)){Stop-Process -Id $p.Id -Force;$exit='owned final editor timed out'}else{$p.Refresh();$exit=$p.ExitCode};$watch.Stop();$after=(Get-FileHash $scene).Hash.ToLower();$files=@();foreach($f in Get-ChildItem $out -File -Filter 'editor-autotest*'){$n="$name-$($f.Name)";Upload $f.FullName $n;$files+=@{path=$f.FullName;name=$n;bytes=$f.Length;sha256=(Get-FileHash $f.FullName).Hash.ToLower()}}
 $rp="$out\$name-smoke.json";@{scope='Fresh final native editor relink against proper production repair; unchanged source/layout objects. Ordinary copied project edit/duplicate/undo/Play/Stop/save; VM software GL functional-only.';exitCode=$exit;seconds=$watch.Elapsed.TotalSeconds;executableSHA256=(Get-FileHash $exe).Hash.ToLower();librarySHA256=$library.archiveSHA256;authoredScene=$scene;sceneBeforeSHA256=$before;sceneAfterSHA256=$after;sceneUnchanged=($before -eq $after);files=$files;freeBytes=(Get-PSDrive C).Free}|ConvertTo-Json -Depth 6|Set-Content $rp -Encoding UTF8;Upload "$out\$name.stdout.log" "$name.stdout.log";Upload "$out\$name.stderr.log" "$name.stderr.log";Upload $rp ([IO.Path]::GetFileName($rp))
 $zip="$scratch\$name-generated.zip";Compress-Archive -LiteralPath (@($exe)+$objects) -DestinationPath $zip;Upload $zip ([IO.Path]::GetFileName($zip));$files=@();foreach($p in @($exe)+$objects){$files+=@{path=$p;name=[IO.Path]::GetFileName($p);bytes=(Get-Item $p).Length;sha256=(Get-FileHash $p).Hash.ToLower()}};$rp="$out\$name-archive.json";@{scope='Owned generated archive only; removal requires independent host SHA proof';archiveName=[IO.Path]::GetFileName($zip);archivePath=$zip;archiveSHA256=(Get-FileHash $zip).Hash.ToLower();archiveBytes=(Get-Item $zip).Length;files=$files}|ConvertTo-Json -Depth 5|Set-Content $rp -Encoding UTF8;Upload $rp ([IO.Path]::GetFileName($rp))
}catch{[string]$_.Exception.Message|Set-Content "$out\$name-error.txt";Upload "$out\$name-error.txt" "$name-error.txt";exit 1}
